def execute_command(image) -> List[ImagePatch]:
    image_patch = ImagePatch(image)
    pedestrians = image_patch.find("pedestrian")
    shops_and_stalls = image_patch.find("shop and stall")

    if not pedestrians or not shops_and_stalls:
        return image_patch

    pedestrian_patches = []
    shop_and_stall_patches = []

    for ped in pedestrians:
        if ped.left < image_patch.width / 2:
            pedestrian_patches.append(ped)

    for shop in shops_and_stalls:
        if shop.right < image_patch.width / 2:
            shop_and_stall_patches.append(shop)

    if not pedestrian_patches or not shop_and_stall_patches:
        return image_patch

    pedestrian_patches.sort(key=lambda p: p.vertical_center)
    shop_and_stall_patches.sort(key=lambda s: s.vertical_center)

    min_distance = float('inf')
    best_pedestrian = None

    for ped in pedestrian_patches:
        for shop in shop_and_stall_patches:
            dist = abs(ped.vertical_center - shop.vertical_center)
            if dist < min_distance:
                min_distance = dist
                best_pedestrian = ped

    return best_pedestrian

